/**
 * CPM（关键路径法）纯函数算法，不依赖 Prisma / NestJS。
 * 输入：项目内活跃任务列表 + 依赖列表；输出：ES/EF/LS/LF/slack/criticalPath/milestones/eta。
 *
 * 约定：
 * - durationDays = estimatedHours / 8，无估时默认 1 天
 * - 起点：无前置依赖的活跃任务 ES = today 00:00 UTC
 * - 依赖传播：
 *   - FS：nextTask.ES = prevTask.EF + lagDays（工作日）
 *   - SS：nextTask.ES = prevTask.ES + lagDays（工作日）
 *   - FF：nextTask.EF = prevTask.EF + lagDays（工作日）
 *   - SF：nextTask.EF = prevTask.ES + lagDays（工作日）
 * - 已完成（done）/已取消（cancelled）任务不参与计算
 * - 周末顺延使用 addWorkdays 函数
 * - 关键路径 = slackDays === 0 的任务链
 * - milestone = 关键路径上 dueAt 非空的任务，或 durationDays === 0 的任务
 */
export interface TaskInput {
    id: string;
    title: string;
    status: string;
    estimatedHours: number | null;
    dueAt: string | null;
}
export interface DependencyInput {
    id: string;
    prevTaskId: string;
    nextTaskId: string;
    type: 'FS' | 'SS' | 'FF' | 'SF';
    lagDays: number;
}
export interface PlanTask {
    id: string;
    title: string;
    status: string;
    durationDays: number;
    es: string;
    ef: string;
    ls: string;
    lf: string;
    slackDays: number;
    critical: boolean;
    milestone: boolean;
    eta: string;
    dueAt: string | null;
}
export interface PlanResult {
    projectId: string;
    calculatedAt: string;
    tasks: PlanTask[];
    criticalPath: string[];
    projectEta: string;
    projectSlackDays: number;
    milestones: string[];
    assumptions: string[];
}
export interface DependencyOutput {
    id: string;
    prevTaskId: string;
    nextTaskId: string;
    type: 'FS' | 'SS' | 'FF' | 'SF';
    lagDays: number;
}
/**
 * 在工作日上加 n 天（跳过周六日）。
 * start 为 ES（00:00 UTC），返回结果也为 00:00 UTC。
 */
export declare function addWorkdays(start: Date, days: number): Date;
/**
 * 在工作日上减 n 天（跳过周六日）。
 */
export declare function subtractWorkdays(start: Date, days: number): Date;
/**
 * 拓扑排序（Kahn 算法），检测环。
 * @returns 拓扑顺序的任务 ID 数组；有环抛 Error
 */
export declare function topologicalSort(taskIds: string[], deps: DependencyInput[]): string[];
/**
 * 主 CPM 计算入口。
 * @param projectId 项目 ID
 * @param tasks 活跃任务列表（已过滤 done/cancelled）
 * @param dependencies 依赖列表（仅活跃任务间的依赖）
 * @returns PlanResult
 */
export declare function calculateCPM(projectId: string, tasks: TaskInput[], dependencies: DependencyOutput[], explicitStartDate?: Date): PlanResult;
